def iq(cid, en, ar, f_en, f_ar, points):
    return {"id": "IQ-" + cid, "competency": cid, "prompt": T(en, ar), "follow_up": T(f_en, f_ar),
            "key_points": [{"t": T(p[0], p[1]), "terms": K(p[2], p[3])} for p in points]}


